      config: AgentLoopConfig(model: testModel, finalizeGate: finalizeGate),
      streamFunction: fake.call,
      toolExecutor:
          toolExecutor ?? (_, _, _) async => ToolExecutionResult.text('ok'),
    );
    return stream.toList();
  }

