void main() {
  AssistantMessage assistant(
    List<ContentBlock> content, {
    StopReason stopReason = StopReason.stop,
  }) => AssistantMessage(
    content: content,
    api: 'test-api',
    provider: 'test-provider',
    model: 'test-model',
    usage: Usage.zero,
    stopReason: stopReason,
    timestamp: DateTime.utc(2026),
  );

  List<AssistantMessageEvent> textTurn(
    String text, {
    StopReason stopReason = StopReason.stop,
  }) {
    final empty = testAssistant();
    final partial = assistant([
      TextContent(text: text),
    ], stopReason: stopReason);
    return [
      StartEvent(partial: empty),
      TextStartEvent(contentIndex: 0, partial: empty),
      TextDeltaEvent(contentIndex: 0, delta: text, partial: partial),
      DoneEvent(reason: stopReason, message: partial),
    ];
  }

  List<AssistantMessageEvent> toolTurn(List<ToolCall> calls) {
    final empty = testAssistant();
    final partial = AssistantMessage(
      content: calls,
      api: 'test-api',
      provider: 'test-provider',
      model: 'test-model',
      usage: Usage.zero,
      stopReason: StopReason.toolUse,
      timestamp: DateTime.utc(2026),
