    required ProcessResult inSession,
    required ProcessResult parity,
  }) {
    final diverged =
        '${inSession.stdout}'.trim() != '${parity.stdout}'.trim() ||
        '${inSession.stderr}'.trim() != '${parity.stderr}'.trim() ||
        inSession.exitCode != parity.exitCode;
